def transform(grid):
    import collections
    g = np.array(grid)
    bg = background(g)
    d = dividers(g)
    vertical = False
    if d["rows"]:
        dpos = d["rows"][0][0]
    else:
        dpos = d["cols"][0][0]
        vertical = True
        g = g.T.copy()
    H, W = g.shape
    out = g.copy()
    for c in (2, 5, 6):
        out[out == c] = bg
    show = (lambda a: a.T) if vertical else (lambda a: a)
    emit(show(out).copy(), "Erase the 5s, 2s and 6s, leaving only the background and the divider line.")
    finals = []
    for y, x in zip(*np.where(g == 2)):
        dist = {(y, x): 0}
        q = collections.deque([(y, x)])
        best = (0, y, x)
        while q:
            cy, cx = q.popleft()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = cy + dy, cx + dx
                if 0 <= ny < H and 0 <= nx < W and g[ny, nx] == 6 and (ny, nx) not in dist:
                    dist[(ny, nx)] = dist[(cy, cx)] + 1
                    if dist[(ny, nx)] > best[0]:
                        best = (dist[(ny, nx)], ny, nx)
                    q.append((ny, nx))
        finals.append((best[1], best[2]))
    for y, x in finals:
        out[y, x] = 2
    emit(show(out).copy(), "Slide each 2 along its attached chain of 6s to the far end of the chain.")
    for y, x in finals:
        my = 2 * dpos - y
        if 0 <= my < H:
            out[my, x] = 5
    emit(show(out).copy(), "Place a 5 at the mirror image of each final 2 across the divider line.")
    return show(out)
